_WINDOWS = Windows(receding_phob=100.0, advancing_phob=120.0, receding_phil=50.0, advancing_phil=70.0)
_C_TRUE = 2.7
_N_SNAPSHOTS = 150
_SAVE = 200
_ONSET = 50_000


def _info(name: str, alpha_deg: float, tau: float, groups: list[str]) -> RunInfo:
    return RunInfo(
        run=f"synthetic/{name}",
        path=Path("synthetic") / name,
        name=name,
        groups=groups,
        nx=201,
        save_interval=_SAVE,
        t_onset=_ONSET,
        tau=tau,
        rho_l=1.0,
        eta=(tau - 0.5) / 3.0,
        gamma=0.00532267,
        gamma_source="analytical",
        drho=1.0,
        g=5e-6,
        alpha_deg=alpha_deg,
        omega=1016.0,
        r0=math.sqrt(1016.0),
        step_x=80.4,
        edge_width=1.0,
        windows=_WINDOWS,
        learning_rate=0.005,
        interface_width=5.0,
    )


def _closure_run(info: RunInfo, rng: np.random.Generator) -> DropletSeries:
    """Snapshots of a droplet that obeys the M6 closure exactly, plus 0.01 LU of position noise."""
    closure = StepClosure(_WINDOWS)
    it = _ONSET + _SAVE * np.arange(1, _N_SNAPSHOTS + 1)
    t = np.concatenate([[0.0], (it - _ONSET) / info.time_scale])
    x, _ = integrate_trajectory(
        t,
        -1.08,
        0.0,
        info.oh,
        info.bo,
        closure.hysteresis,
        lambda v: _C_TRUE * closure.base(v) ** 2,
        breakpoints=closure.breakpoints,
        dt_max=5e-3,
    )
    x = x[1:]
    base = np.array([closure.base(v) for v in x]) * info.r0
    cm = info.step_x + info.r0 * x
    noise = rng.normal(0.0, 0.01, (3, x.size))
    scales = MetricScales(
        rho_mean=0.5,
        sigma_measured=None,
        sigma_analytical=info.gamma,
        nu=info.eta,
        r_zero=18.0,
        r_zero_is_fallback=False,
        offset_x=info.step_x,
        incl_deg=info.alpha_deg,
        save_interval=_SAVE,
        wall_edge="bottom",
    )
    return DropletSeries(
        iteration=it,
        avg_u_x=np.gradient(cm, it),
        avg_u_y=np.zeros(x.size),
        avg_x_location=cm - info.step_x,
        cll_left=cm - base / 2 + noise[0],
        cll_right=cm + base / 2 + noise[1],
        theta_left=np.array([closure.trailing_angle(v) for v in x]),
        theta_right=np.array([closure.leading_angle(v) for v in x]),
        cm_x=cm + noise[2],
        cm_y=np.full(x.size, 12.0),
        scales=scales,
    )


@pytest.fixture(scope="module")
def results(tmp_path_factory):
    rng = np.random.default_rng(7)
    infos = [
        _info("fast", 60.0, 0.99, ["inc", "tau"]),
        _info("slow", 45.0, 1.10, ["inc", "tau"]),
        _info("pinned", 10.0, 0.99, ["inc"]),
    ]
    loaded = [(info, _closure_run(info, rng)) for info in infos]
    out = tmp_path_factory.mktemp("force_balance")
    cfg = ForceBalanceConfig(
        root=out,
        output_dir=out,
        groups={"inc": [i.run for i in infos], "tau": [i.run for i in infos[:2]]},
        settings=AnalysisSettings(bootstrap_samples=20),
    )
    res = analyse_runs(cfg, loaded, None, AssumptionLog(), lambda _msg: None, detailed=True)
    write_tables(res, out)
    res.figures = make_focus_figures(res, out / "figures", lambda _msg: None)
    res.figures += make_figures(res, out / "figures" / "detailed", lambda _msg: None)
    report = write_report(res, out)
    return res, out, report


def test_closure_fit_recovers_the_generating_friction(results):
    res, _, _ = results
    assert res.fit("M6").params["c_geom"] == pytest.approx(_C_TRUE, rel=0.05)


def test_pinned_run_is_classified_and_predicted_pinned(results):
    res, _, _ = results
    row = res.hysteresis.set_index("name").loc["pinned"]
    assert row["observed"] == "pinned"
    assert row["predicted"] == "pinned"


def test_moving_runs_hold_the_trailing_line_at_the_step(results):
    res, _, _ = results
    held = res.hysteresis.set_index("name")["hold_dX"]
    assert np.isfinite(held.loc["fast"])
    assert held.loc["fast"] > 0.0


def test_outputs_are_written(results):
    _, out, report = results
    tables = (
        "runs_inventory.csv",
        "points_all.csv",
        "fits.json",
        "model_comparison.csv",
        "ladder_errors.csv",
        "missing_by_phase.csv",
        "beta_geometry_laws.csv",
        "lambda_by_phase.csv",
    )
    for name in tables:
        assert (out / name).is_file()
    for name in (
        "F1a_ladder_si",
        "F3a_missing_heatmap",
        "F4_beta_scaling",
        "F5_ladder_summary",
        "F6a_lambda_time",
        "F6b_lambda_phases",
    ):
        assert (out / "figures" / f"{name}.png").is_file()
    assert (out / "figures" / "detailed" / "08_scaling_collapse.pdf").is_file()
    assert (out / "report_detailed.md").is_file()
    text = report.read_text(encoding="utf-8")
    assert "## 1. The SI model against the data-filled model" in text
    assert "## 3. What beta depends on" in text
    assert "## 4. The SI friction coefficient lambda (M7)" in text


def test_si_lambda_grows_with_the_base_when_friction_is_quadratic(results):
    """The runs obey ``beta = c A**2/Omega``, so ``lambda/eta = beta/A`` scales with the base width."""
    res, _, _ = results
    closure = StepClosure(_WINDOWS)
    table = res.focus.lambda_phases.set_index(["name", "phase"])
    ratio = table.loc[("fast", "post"), "ratio_to_pre"]
    assert ratio == pytest.approx(closure.a3 / closure.a1, rel=0.1)


def test_missing_forces_add_up_to_the_si_residual(results):
    res, _, _ = results
    f = res.focus.forces
    total = f["dF_w"] + f["dF_H"] + f["dF_beta"] + f["R"]
    np.testing.assert_allclose(total.to_numpy(), f["F_res_SI"].to_numpy(), atol=1e-12)


def test_m7_residual_differs_from_r_only_by_the_friction_law(results):
    res, _, _ = results
    f, p = res.focus.forces, res.points
    beta_m4 = res.fit("M4").params["c_lub"] * p["A_lu"] ** 2 / p["Omega"]
    beta_m7 = res.fit("M7").params["lambda_eta"] * p["A_lu"]
    expected = f["R"] + (beta_m7 - beta_m4) * p["Ca_cm"]
    np.testing.assert_allclose(f["R_M7"].to_numpy(), expected.to_numpy(), atol=1e-12)


def test_closure_run_passes_every_phase_in_order(results):
    res, _, _ = results
    phases = res.focus.forces.loc[res.focus.forces["name"] == "fast", "phase"].tolist()
    order = [p for i, p in enumerate(phases) if i == 0 or p != phases[i - 1]]
    assert order == ["pre", "lead jump", "straddle", "hold", "post"]


def test_identical_interface_widths_are_reported(results):
    res, _, _ = results
    assert any("W/R0" in note for note in res.focus.notes)


def test_missing_run_is_logged_and_skipped(tmp_path):
    cfg = ForceBalanceConfig(root=tmp_path, output_dir=tmp_path, groups={"a": ["nowhere"]})
    log = AssumptionLog()

    assert load_runs(cfg, None, log) == []
    assert log.lines() == ["[nowhere] SKIPPED: path or config.toml does not exist"]


def test_identical_trajectories_are_counted_once_with_merged_groups(tmp_path, monkeypatch):
    series = _closure_run(_info("twin", 60.0, 0.99, ["a"]), np.random.default_rng(1))

    def fake_load(rel, groups, _cfg, _log):
        return _info(rel, 60.0, 0.99, list(groups)), series

    monkeypatch.setattr(runs_module, "load_run", fake_load)
    cfg = ForceBalanceConfig(root=tmp_path, output_dir=tmp_path, groups={"a": ["one"], "b": ["two"]})
    log = AssumptionLog()

    loaded = load_runs(cfg, None, log)

    assert len(loaded) == 1
    assert loaded[0][0].groups == ["a", "b"]
    assert loaded[0][0].duplicates == ["two"]


def test_si_calibration_recovers_the_plateau_friction():
    """A run that obeys the SI model exactly: the plateau gives back beta_f, the SI rung follows it."""
    info = _info("si", 60.0, 0.99, ["inc"])
    beta_true = 5.0
    width = 1.15
    it = _ONSET + _SAVE * np.arange(1, _N_SNAPSHOTS + 1)
    t = np.concatenate([[0.0], (it - _ONSET) / info.time_scale])
    regimes = [Regime(_WINDOWS.h1, beta_true), Regime(_WINDOWS.h2, beta_true), Regime(_WINDOWS.h3, beta_true)]
    x, _ = piecewise_trajectory(t, -1.08, 0.0, info.oh, info.bo, (-width / 2, width / 2), regimes)
    series = _rigid_series(info, x[1:], width)
    df = build_point_table(info, series, AnalysisSettings(), AssumptionLog())

    cal = calibrate(df, info, global_beta=1.0, settings=AnalysisSettings())

    assert cal.beta_source == "pre-step plateau"
    # A finite pre-step stretch (here ~5 relaxation times) ends just short of Ca_inf, so beta_f reads a
    # little high; that bias belongs to any plateau calibration, not to the estimator.
    assert cal.beta_f == pytest.approx(beta_true, rel=0.03)
    assert cal.width == pytest.approx(width, abs=1e-3)


def _rigid_series(info: RunInfo, x: np.ndarray, width: float) -> DropletSeries:
    """A rigid droplet of base *width* (units of R0) at centre positions *x*, angles at the SI's bounds."""
    noise = np.random.default_rng(5).normal(0.0, 0.01, (3, x.size))
    cm = info.step_x + info.r0 * x
    half = 0.5 * width * info.r0
    trail_on_phob = cm - half < info.step_x
    lead_on_phob = cm + half < info.step_x
    return DropletSeries(
        iteration=_ONSET + _SAVE * np.arange(1, x.size + 1),
        avg_u_x=np.zeros(x.size),
        avg_u_y=np.zeros(x.size),
        avg_x_location=cm - info.step_x,
        cll_left=cm - half + noise[0],
        cll_right=cm + half + noise[1],
        theta_left=np.where(trail_on_phob, _WINDOWS.receding_phob, _WINDOWS.receding_phil),
        theta_right=np.where(lead_on_phob, _WINDOWS.advancing_phob, _WINDOWS.advancing_phil),
        cm_x=cm + noise[2],
        cm_y=np.full(x.size, 12.0),
        scales=_closure_run(info, np.random.default_rng(0)).scales,
    )
